#define WIDTH 320.
#define HEIGHT 240.
#define STEPS 8.

float hash12(vec2 p) {
    float h = dot(p,vec2(127.1,311.7));	
    return fract(sin(h)*43758.5453123);
}
vec2 r(vec2 v) { return vec2(floor(v.x * WIDTH) / WIDTH, floor(v.y * HEIGHT) / HEIGHT); }

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = r(fragCoord / iResolution.xy);

    vec3 col = texture(iChannel0,uv).rgb;
    float c = round((col.r + col.g + col.b) / 3. * STEPS) / STEPS;

    float val = hash12(r(vec2(mod(uv.x+c*iTime,1.),uv.y)));
    fragColor = vec4(vec3(val), 1.0);
}
